"use strict";(self.webpackChunktest_website=self.webpackChunktest_website||[]).push([[49836],{965447:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>s,contentTitle:()=>h,default:()=>w,frontMatter:()=>i,metadata:()=>a,toc:()=>d});var a=n(905537),o=n(474848),r=n(28453);const i={tags:["UFO","need_ai","amendmark","2024-12"]},h="Tony Rodrigues \u306e\u8b1b\u6f14\u52d5\u753b : \u6587\u5b57\u8d77\u3053\u3057",s={authorsImageUrls:[]},d=[{value:"\u524d\u7f6e\u304d",id:"\u524d\u7f6e\u304d",level:2},{value:"\u52d5\u753b(1:28:43)",id:"\u52d5\u753b12843",level:2},{value:"\u52d5\u753b\u6982\u8981\u6b04",id:"\u52d5\u753b\u6982\u8981\u6b04",level:3},{value:"FasterWhisper AI(large-v2 model) + DeepL(2024-07 model)",id:"fasterwhisper-ailarge-v2-model--deepl2024-07-model",level:2}];function l(e){const t={a:"a",h2:"h2",h3:"h3",hr:"hr",p:"p",...(0,r.R)(),...e.components},{Details:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h2,{id:"\u524d\u7f6e\u304d",children:"\u524d\u7f6e\u304d"}),"\n",(0,o.jsx)(t.p,{children:"Tony Rodrigues \u306e\u8b1b\u6f14\u52d5\u753b\u304b\u3089\u3002\u6587\u5b57\u8d77\u3053\u3057 \u3092\u3064\u3051\u3066\u304a\u304f\u3002\u5f8c\u65e5\u3001\u548c\u8a33\u3001\u9759\u6b62\u753b\u3001AI \u8981\u7d04 \u3092\u8ffd\u52a0\u4e88\u5b9a\u3002"}),"\n",(0,o.jsx)(t.p,{children:"\u52d5\u753b\u306b\u767b\u5834\u3057\u3066\u3044\u308b\u9759\u6b62\u753b\u306b\u306f\u3001\u5f7c\u306e\u8a3c\u8a00\u304c\u4e8b\u5b9f\u3067\u306f\u3042\u308a\u3048\u306a\u3044\u72b6\u6cc1\u304c\u63cf\u304b\u308c\u3066\u3044\u308b\u304c\u8ab0\u3082\u6c17\u3065\u3044\u3066\u3044\u306a\u3044\u6a21\u69d8\u3002"}),"\n",(0,o.jsx)(t.h2,{id:"\u52d5\u753b12843",children:"\u52d5\u753b(1:28:43)"}),"\n",(0,o.jsx)(t.p,{children:"Detroit Disclosure Conference - Tony Rodrigues: The Secret Space Program"}),"\n",(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/eSfuZp76NXE?si=mK77oSHKU27N0wj1",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.a,{href:"http://www.youtube.com/watch?v=eSfuZp76NXE",children:"www.youtube.com/watch?v=eSfuZp76NXE"})}),"\n",(0,o.jsx)(t.h3,{id:"\u52d5\u753b\u6982\u8981\u6b04",children:"\u52d5\u753b\u6982\u8981\u6b04"}),"\n",(0,o.jsx)(t.p,{children:"21,900 views  Sep 21, 2019"}),"\n",(0,o.jsxs)(n,{children:[(0,o.jsx)("summary",{children:"\u25bc\u5c55\u958b"}),(0,o.jsx)(t.p,{children:"\u30c7\u30c8\u30ed\u30a4\u30c8\u30fb\u30c7\u30a3\u30b9\u30af\u30ed\u30fc\u30b8\u30e3\u30fc\u4f1a\u8b70 - \u30c8\u30cb\u30fc\u30fb\u30ed\u30c9\u30ea\u30b2\u30b9 The Secret Space Program"}),(0,o.jsx)(t.p,{children:"SSP\u306820 and Back Program\u306b\u95a2\u3059\u308b\u30d7\u30ec\u30bc\u30f3\u30c6\u30fc\u30b7\u30e7\u30f3\r\n2019\u5e749\u67088\u65e5"}),(0,o.jsx)(t.p,{children:"\u30c8\u30cb\u30fc\u306f\u300c20 and Back Program\u300d\u3068\u3057\u3066\u77e5\u3089\u308c\u3064\u3064\u3042\u308b\u3082\u306e\u306e\u30a4\u30f3\u30b5\u30a4\u30c0\u30fc\u3067\u3042\u308a\u4f53\u9a13\u8005\u3067\u3042\u308b\u3002\u5f7c\u306b\u4f55\u304c\u8d77\u3053\u308a\u3001\u3069\u306e\u3088\u3046\u306b\u305d\u308c\u3092\u514b\u670d\u3057\u305f\u304b\u3092\u8a73\u3057\u304f\u8aac\u660e\u3059\u308b\u3002\u5f7c\u306f\u69d8\u3005\u306a\u592a\u967d\u7cfb\u5916\u60d1\u661f\u30b3\u30ed\u30cb\u30fc\u3084\u5b87\u5b99\u7a2e\u65cf\u3092\u8a8d\u8b58\u3057\u3066\u304a\u308a\u3001\u3053\u306e\u8cb4\u91cd\u306a\u516c\u306e\u5834\u3067\u81ea\u8eab\u306e\u7d4c\u9a13\u306b\u3064\u3044\u3066\u8a71\u3059\u4e88\u5b9a\u3067\u3042\u308b\u3002ExoNews\u3067\u306e\u30de\u30a4\u30b1\u30eb\u30fb\u30b5\u30e9\u535a\u58eb\u3068\u306e\u30a4\u30f3\u30bf\u30d3\u30e5\u30fc\u306f10\u4e07\u30d3\u30e5\u30fc\u3092\u8d85\u3048\u305f\u3002"}),(0,o.jsx)(t.p,{children:"\u30b5\u30c3\u30e9\u535a\u58eb\u306b\u3088\u308c\u3070\u3001\u300c\u30ed\u30c9\u30ea\u30b2\u30b9\u306e\u8a71\u3067\u5370\u8c61\u7684\u3060\u3063\u305f\u306e\u306f\u3001\u65e7\u4e16\u4ee3\u306e\u30c9\u30a4\u30c4\u306e\u5b87\u5b99\u8239\u3092\u6539\u9020\u6f5c\u6c34\u8266\u3068\u8868\u73fe\u3057\u305f\u3053\u3068\u3067\u3059\u3002\u3053\u308c\u306f\u3001\u30c8\u30f3\u30d7\u30ad\u30f3\u30b9\u304c\u672a\u767a\u8868\u306e\u30a4\u30f3\u30bf\u30d3\u30e5\u30fc\u3067\u8a9e\u3063\u305f\u3001\u30a2\u30e1\u30ea\u30ab\u6d77\u8ecd\u306e\u6700\u521d\u306e\u5b87\u5b99\u8239\u304c\u30ce\u30fc\u30c1\u30e9\u30b9\u7d1a\u539f\u5b50\u529b\u6f5c\u6c34\u8266\u3092\u6539\u9020\u3057\u305f\u3082\u306e\u3067\u3042\u308b\u3068\u3044\u3046\u8a18\u8ff0\u3068\u4e00\u81f4\u3057\u3066\u3044\u305f\u3002\u79c1\u304c\u77e5\u308b\u9650\u308a\u3001\u3053\u306e\u975e\u5e38\u306b\u91cd\u8981\u306a\u60c5\u5831\u3092\u660e\u3089\u304b\u306b\u3057\u305f\u306e\u306f\u30ed\u30c9\u30ea\u30b2\u30b9\u304c\u521d\u3081\u3066\u3067\u3042\u308b\u3002\u300d"}),(0,o.jsx)(t.p,{children:"Detroit Disclosure Conference - Tony Rodrigues: The Secret Space Program"}),(0,o.jsx)(t.p,{children:"Presentation on the SSP and 20 and back program\r\nSeptember 8th, 2019"}),(0,o.jsx)(t.p,{children:"Tony is an insider and experiencer of what is becoming known as the '20 and Back Program'. He will detail what has happened to him and how he overcame it. He has awareness of various exoplanetary colonies and space species, and will be speaking about his experience in this rare public appearance. His interviews with Dr. Michael Salla on ExoNews have received over one hundred thousand views."}),(0,o.jsx)(t.p,{children:'According to Dr. Salla, \u201cAmong the things that impressed me in Rodrigues story was his description of the older generation of German spacecraft as retrofitted submarines. This was consistent with Tompkins\u2019 description of the first US Navy space craft being retrofitted Nautilus class nuclear submarines which he shared in an unpublished interview. As far as I\u2019m aware, Rodrigues was the first person to reveal this very significant piece of information."'})]}),"\n",(0,o.jsx)(t.h2,{id:"fasterwhisper-ailarge-v2-model--deepl2024-07-model",children:"FasterWhisper AI(large-v2 model) + DeepL(2024-07 model)"}),"\n",(0,o.jsxs)(n,{children:[(0,o.jsx)("summary",{children:"\u25bc\u539f\u6587 \u5c55\u958b"}),(0,o.jsx)(t.p,{children:"Tony Rodriguez, member of the Secret Space Program's 20 and Back Program, is here with us today.\r\nI hope you guys enjoy what he has to say. I'm very looking forward to hearing what you've got to say, man.\r\nShoot. Serious? Series? Like the TV show? Like a series.\r\nWelcome Tony Rodriguez, everybody. A big round of applause. Glad to have him.\r\nHello. It's good to be here. I've got to admit, I'm a little nervous.\r\n(0:00:40)"}),(0,o.jsx)(t.p,{children:"You never know how much the crowd knows. It's a complicated subject, as anybody can guess.\r\nHow many people here have heard of the 20 and Back Technology or the 20 and Back Programs?\r\nWow, so quite a bit. That's way more than I expected.\r\nWhat I've found is, what happened to me is I was taken.\r\n(0:01:03)"}),(0,o.jsx)(t.p,{children:"I was about 10 years old. It was 1982. I'm from Michigan. I'm from Ypsilanti, the Ypsilanti area. And I was taken and did a 20 and Back. And I was not groomed for it or used for it for an official, like a professional purpose.\r\nI was taken kind of as an extra by people that had access to the program.\r\nKind of like if it were Coca-Cola and they were running through a special, whatever, a cherry version of Coke. And they shut it down. They shut the program down. And they said, you know what? Run me through six more cases for myself.\r\n(0:01:32)"}),(0,o.jsx)(t.p,{children:"That's kind of what I was and the kids that I was with through the program happened.\r\nWhat I've found is since I've come forward, I've got my memories back in May of 2015. The major memory recall. I always had memories, but they didn't make any sense to me.\r\nWhen could I have been on a spaceship or on the planet Ceres?\r\nI had chronological memory of my life.\r\n(0:01:54)"}),(0,o.jsx)(t.p,{children:"So after I came forward, I did a few interviews.\r\nAnd what I found was that explaining the 20 and Back technology to somebody that doesn't know, pretty much everybody in America is, or in the world for that matter, is very accepting of ETs. Any kind of spacecraft. The fact that we're not alone.\r\nIt's kind of a no-brainer when you do the math on the stars, the amount of stars.\r\n(0:02:18)"}),(0,o.jsx)(t.p,{children:"Everybody can accept that quickly, but when you start telling people that you were taken and that there was a time travel component. You were taken, you lived 20 years, there may have been cloning involved, and there was a time travel component.\r\nThey put you back and you were only gone about 15 or 30 minutes from your home.\r\nAnd you were right back to being, I was taken when I was 10, I lived through an adult, and then somehow put right back to being a 10-year-old 30 minutes later.\r\n(0:02:40)"}),(0,o.jsx)(t.p,{children:"When you tell people that are unaware of that stuff, that there's a time travel component, you get the thousand-yard stare. That's when the disbelief, nobody wants to believe that.\r\n(0:02:51)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"But that's how I experienced it. And not being a pro, I'm going to skip ahead to help explain that for the people that are unaware of what I'm talking about.\r\nJust how it shakes out. There's a diagram. I'm going to skip to a slide quicker.\r\nSo, the way I've opened up many talks is that, you know, I was born in 1972, I'm about 47 years old, but I have 67 years worth of memories.\r\n(0:03:40)"}),(0,o.jsx)(t.p,{children:"And what happened was, I'm going to use this pointer, I was born here, and when I was 10, well it was the year, it was the school year, I was 9 to 10, and 81 to 82. I went to school with a kid who came in and I was in the talented and gifted program, TAG they called it, and we met every Wednesday in the library for advanced learning.\r\n(0:04:03)"}),(0,o.jsx)(t.p,{children:"There was a kid in there who identified himself as the son of an Illuminati. He said, my dad's an Illuminati, what's your dad do?\r\nAnd we were boys at that point, and he was very arrogant, so was I. I was kind of a cocky kid, and we didn't get along.\r\nLater that year, in April, we had the science fair, and his dad came in and was the judge.\r\n(0:04:23)"}),(0,o.jsx)(t.p,{children:"Our teacher for that program said he was the most pedigreed, educated man she'd ever met, or even heard of.\r\nThat he had more degrees than anybody she ever knew.\r\nAnd in the cafeteria that day setting up, he pointed me out to him and said, that's that boy I told you about. He didn't like me.\r\nAnd it was that night, probably.\r\n(0:04:42)"}),(0,o.jsx)(t.p,{children:"But anyhow, I was taken, and then woke up without any memory of my mom, dad, my wife, my sister.\r\nI woke up with complete amnesia, and lived for 20 years in black programs.\r\nI did about 6 years on Earth, and went through a few programs there, and then was sold off. What they told me is, I was sold off to the military, and did 8 to 12 years in space.\r\n(0:05:05)"}),(0,o.jsx)(t.p,{children:"And I guess aside from the MUFON presentation, what I want to say is that there's already a human presence in our solar system, and a vast infrastructure that exists. There are already colonies that are built in planetoids, and on space stations in our solar system.\r\nThere's actually quite a bit of commerce, and quite a bit of people.\r\nHas anybody heard of Randy Kramer? A few people?\r\n(0:05:30)"}),(0,o.jsx)(t.p,{children:"So, Randy did time, was a Mars Force Special Marine Corps, and he says there's about 10.5 million people living on Mars at the moment.\r\nSo, what happened was, as I was traded, I went through program to program, depending on what I had aptitude for at the time.\r\nAnd I ended up living about 12 years on Ceres, where I worked on interstellar craft on trade missions.\r\n(0:05:58)"}),(0,o.jsx)(t.p,{children:"The first 8 years of that, I was a repairman, kind of a repair function on an older ship, an antiquated ship that was a converted submarine.\r\n(0:06:06)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"And then when that ship was decommissioned, we went to a bigger, modern freighter ship, where I was promoted and became a cargo engineer.\r\nOur primary... this thing... am I too close to this?\r\nOur primary mission was interstellar trade for technology.\r\nThe Ceres Colony Corporation is completely... the planetoids in the solar system are broken up into corporations.\r\nSo, there's the Mars Colony Corporation, the Ceres Colony Corporation. The Ceres Colony was ran by breakaway Germans, and their primary mission was to trade with extraterrestrial races for technology.\r\n(0:06:39)"}),(0,o.jsx)(t.p,{children:"They didn't care what they traded, or how they got it.\r\nThere were many times that we stole from... we outright stole from them.\r\nAnd because their mission was mandated, was purely to get technology.\r\nSo, at the end of that 20 years, and that's how the program works, there was a series of... they returned me to a moon base, a lunar base, and I went through a series of surgeries, and put into a machine that was very painful.\r\n(0:07:06)"}),(0,o.jsx)(t.p,{children:"Aaron?\r\nI'm sorry, the monitor is closed.\r\nI see.\r\nHow's that?\r\nSounds better to me.\r\nAnd then returned to my life, and I woke up back in my bedroom, even though it felt like 20 years had passed, I had no memory of it.\r\nI was returned right back to 1982, to the same night I was taken, and I remember waking up the next morning and going, this is my old life, and it felt like that distance of time had passed, even though I had no memory, at that point, of these 20 years.\r\n(0:07:42)"}),(0,o.jsx)(t.p,{children:"So, I woke up here with no memory of this life, lived this life, and then was put back and had no memory of this life, and then lived my life.\r\nAnd during that time, whenever something traumatic happened over here, at times when I was injured, I would recall it in my normal life.\r\nBut those memories, like I said, didn't make sense.\r\nThe difference between... I get asked all the time, well, how do you know it's not a dream?\r\n(0:08:09)"}),(0,o.jsx)(t.p,{children:"How do you know you weren't just having a vivid dream of all this?\r\nIn the memory, I had memories of how I got there.\r\nMemories of getting up in the morning, brushing my teeth, going to the bathroom, going to work, going through whatever event that I remember, and then going home.\r\nAnd that's not something you get in a dream.\r\nI'm going to flash you guys, hopefully there's no epileptics.\r\n(0:08:38)"}),(0,o.jsx)(t.p,{children:"I'll start at the beginning and get going.\r\nI feel like I'm chewing some time up here.\r\nSo, that's the planetoid series.\r\nThe base, the entrance, everything was underground.\r\nThere was a series of cities in caverns.\r\nThe Germans, after World War II, had acquired space flight.\r\nWorld War I was about money.\r\nWorld War II was about interstellar flight.\r\nAnd they lost the war, but broke away into the solar system.\r\n(0:09:09)"}),(0,o.jsx)(t.p,{children:"And one of the bases they found abandoned was the Ceres Colony, which was built by some other race, and they went in and began to build structures and adapt it for themselves.\r\n(0:09:20)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"There were about 225,000 people living there when I was there, and about 40,000 or 50,000 slaves.\r\nAnd that's what I was, basically was a slave.\r\nUp here is the Al-Hana Mons that NASA calls a cryovolcano, but the radial handle was pyramid base for the ships when they would return.\r\nAnd on the backside of that, there's a crater.\r\nI'll show you in another slide later.\r\n(0:09:43)"}),(0,o.jsx)(t.p,{children:"And inside that crater, there are smaller craters that they call cold traps, where the sun never shines inside of it.\r\nAnd inside one of those, there were large doors that opened up into a network of hangar bays that were miles and miles long.\r\nIt was a vast complex.\r\nAnd then it went into a military base that was connected to all the other cities around the inside of the planet by trains.\r\n(0:10:05)"}),(0,o.jsx)(t.p,{children:"So people didn't have their own cars.\r\nEverybody took a train somewhere, and then you just walked to where you were going.\r\nThe entire planet is about 580 miles in diameter.\r\nIt's a small thing.\r\nThey had artificial gravity.\r\nAnd the biggest advancement, I think, from the secret space program to what we have today, the most significant advancement is gravity manipulation, the ability to manipulate gravity artificially.\r\n(0:10:29)"}),(0,o.jsx)(t.p,{children:"And that's what gives the ships the speed and the ability to fly like they do.\r\nAnd it gives them the ability to set up bases on small planetoids and not have to fight the gravity.\r\nThat was me when I was 10. So that's about the age... that's what I looked like when I was taken.\r\nAnd that picture was taken, I think, in Boy Scouts. So that's something I dug up.\r\n(0:10:53)"}),(0,o.jsx)(t.p,{children:"I did not get returned in that happy mood, though.\r\nI was a different person.\r\nThe day I was taken and the morning I woke up, I was a completely different person the next day.\r\nThat's my house in Ipsy. So we had about 13 acres.\r\nAnd the night I was taken, we were being buzzed by a craft.\r\nThere was bright lights outside.\r\nWe had the old ringer phone with the long cord on it downstairs.\r\n(0:11:17)"}),(0,o.jsx)(t.p,{children:"And it just rang and rang and rang in the middle of the night.\r\nNobody answered it, which was strange.\r\nBecause whenever it rang, my mom always got up and answered the phone.\r\nBut she wouldn't answer it that night.\r\nThere were bright lights outside.\r\nAnd I remember thinking, why is nobody answering the phone?\r\nAnd it went on.\r\nThere was a certain time when it would stop.\r\n(0:11:35)"}),(0,o.jsx)(t.p,{children:"And there was an orb that came into my room.\r\nIt was a bright blue orb.\r\nIt flew in and I remember I kind of giggled with it.\r\nIt interacted with me somehow and I giggled.\r\nAnd then it flew out and down the stairs.\r\nAnd then there was silence.\r\nAnd I fell back to sleep and woke up.\r\nLet me see if this is the next one.\r\n(0:11:52)"}),(0,o.jsx)(t.p,{children:"There's my school I went to.\r\n(0:11:53)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"I woke up with one of those guys in my face.\r\nHe was standing over me smiling.\r\nAnd I thought at the time, you know, my dad was a practical joker in those days.\r\nAnd I thought it was my dad with a mask.\r\nAnd I said, Dad, take off the mask.\r\nIt's not funny.\r\nAnd I reached up and touched its face.\r\nAnd it was wet and cold.\r\n(0:12:14)"}),(0,o.jsx)(t.p,{children:"It wasn't like a person.\r\nIt was cold.\r\nAnd you could feel pores.\r\nLike it had really extra large pores on it.\r\nAnd at that moment I went to scream.\r\nI freaked out, you know.\r\nAt that point I knew there was some stranger in my room.\r\nAnd I panicked.\r\nAnd it hit me on the back of the neck, I think.\r\nThere was some pain.\r\n(0:12:32)"}),(0,o.jsx)(t.p,{children:"And there were some guys around.\r\nAnd at the foot of my bed, my bed had a dresser in it so it was about three feet tall.\r\nAnd at the foot of my bed I saw two or three of these guys coming around.\r\nAnd they picked me up out of my bed.\r\nThey were smaller reptiles, stocky built.\r\nAnd they picked me up out of my bed and carried me to the foot of my bed where there was a bright flash.\r\n(0:12:56)"}),(0,o.jsx)(t.p,{children:"And I woke up on a table.\r\nI lost consciousness and woke up like in a laboratory on a table.\r\nAnd I honestly thought that this was first contact.\r\nI thought, boom, aliens are landing.\r\nI thought that that was the day.\r\nAnd the next day it was going to be in the news that they took me.\r\nI thought that was a first contact thing and the world was going to change.\r\n(0:13:19)"}),(0,o.jsx)(t.p,{children:"And so I was just excited.\r\nI was stoked.\r\nAnd at that point they began to communicate telepathically and told me they were going to run some tests on me.\r\nAnd to see if I qualified for what they needed me for.\r\nAnd they were going to take me for 20 years.\r\nAnd I said, no, no, I can't do that.\r\nI have my mom and dad and my sister.\r\n(0:13:36)"}),(0,o.jsx)(t.p,{children:"I can't be away from my family for 20 years and grow up.\r\nAnd he said, no, this one said no.\r\nAnd explained to me that there was a time travel and I'd be back the next day.\r\nAnd that I was very lucky to be chosen for what they wanted to do.\r\nAnd that I would be able to tell everybody about the things that I did for 20 years.\r\n(0:13:53)"}),(0,o.jsx)(t.p,{children:"And it would be just the next day.\r\nSo I agreed.\r\nThey did a test.\r\nThey had to wait for the results of the test.\r\nThey said it was based on genetics.\r\nAnd that I just barely had the genetics.\r\nApparently some people have the genetics to do it twice.\r\nOr do it 20 and back and then live the 20 years and then do another one.\r\n(0:14:10)"}),(0,o.jsx)(t.p,{children:"So some people can go for 40 years.\r\n(0:14:12)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"It's a life extension technology that's been traded with extraterrestrial races for life extension.\r\nAnd apparently in my case it was abused.\r\nAnd I was used for slavery.\r\nAnd I've said this in other times, other interviews, is that I think everybody here, I think mankind as a whole, when you think about having the ability to take somebody and erase their memory and program their mind to do whatever you want, how fast would it be, how fast would your morals kind of slide downhill if you had that ability?\r\n(0:14:44)"}),(0,o.jsx)(t.p,{children:"If you could do whatever you wanted to anybody and then erase their memory and put them back just how you found them, I mean, would we all act morally in that situation?\r\nAnd I think that these government programs originally got this tech, you know, back in the 40s, 50s, and started up, meant well, to do military purposes.\r\nAnd, like I said, like the extra cases of Coca-Cola that went through, people that have access to this stuff used it on kids like me to do whatever they wanted.\r\n(0:15:12)"}),(0,o.jsx)(t.p,{children:"Unfortunately, some of the darker stuff that happened to me afterwards is also my best evidence.\r\nSo I will share it with you and it's hard for me to explain it to people because in order to believe a lot of the things that I have to say, you have to unbelieve some things you know.\r\nAnd so I'll go on to that. I don't even know what the next one is.\r\n(0:15:35)"}),(0,o.jsx)(t.p,{children:"I'm having a problem here.\r\nSo after I had agreed to the program, they put me back on a table and put a sheet over me. It was just like that scene in Fire in the Sky where a sheet came over me and vacuumed to the table tight like a latex.\r\nAnd they cut a spot out so my eye was exposed, I could see, and they cut out my mouth so I could breathe.\r\n(0:16:07)"}),(0,o.jsx)(t.p,{children:"And they put a needle, you know, like on an arm of a robot and a needle went in.\r\nAnd it felt like, you know, if you've ever been punched hard enough, anybody that's been punched hard enough to where you saw stars, that's kind of what it felt like.\r\nAnd, you know, like I saw stars. And I woke up with no memory of mom and dad.\r\n(0:16:25)"}),(0,o.jsx)(t.p,{children:"I woke up in an air base.\r\nSo this thing's... Aaron? So this thing's lost batteries.\r\nMaybe that's what I did.\r\nThere it is. There we go.\r\nOkay. So it turns out I was in the Inyokern Air Base area and there was a doctor there, a tall man who I've since identified and I won't share his name.\r\nThere's a lot of reasons... I've shared the names of people that I've found through the 20 and back and the locations with lots of researchers, but I don't do it publicly.\r\n(0:17:03)"}),(0,o.jsx)(t.p,{children:"I think it's just safer that way.\r\nBut anyhow, there was a man there was a doctor and a nurse and he gave me a standard physical.\r\n(0:17:09)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"I was in an old, like a hospital bed. It was a portable, like a small building.\r\nAnd he asked me questions. Do you remember your mom? No. Do you remember your dad? No. And I had no idea where I was, who I was or anything.\r\nAnd he said, that's because you're a clone.\r\nAnd that I was going to be programmed to do some tasks.\r\n(0:17:31)"}),(0,o.jsx)(t.p,{children:"So I slept there and after that, in the months to come, we became a trauma-based mind control program, exactly like information that I've dug up on the MKUltra stuff.\r\nSo since then, I've been able to find the program and funding for some of the offshoots of that program that I was in and from the CIA declassified online library.\r\nSo this is more... it was in these buildings here.\r\n(0:17:59)"}),(0,o.jsx)(t.p,{children:"At least... so I've never visited this place yet in my life as Tony, but it's exactly how I remember it from those days.\r\nAll three of those buildings were leased for a short time.\r\nAnd it was myself and maybe a dozen other kids, about a dozen total, of kids that went through this.\r\nAnd what it was, was, you know, they would do something painful to us.\r\n(0:18:24)"}),(0,o.jsx)(t.p,{children:"They had sleep deprivation. They gave us drugs.\r\nAnd then they would... they hung us in chairs with things shocking us on our head, with helmets that had electrodes that shocked us and we watched movies.\r\nAnd the movies had really fast subliminal messages in them.\r\nAnd they were a combination of cartoons, kids cartoons, and then like animals being slaughtered.\r\nAnd just trauma stuff.\r\nAnd so that happened most of the time.\r\n(0:18:48)"}),(0,o.jsx)(t.p,{children:"And then... well, they started with the sleep deprivation.\r\nThey started every 15 minutes at night waking us up.\r\nAnd I totally lost track of time and what happened after that.\r\nBut the end result of that program was that if we were shocked by... we felt an electrical shock, we would stop whatever we were doing and we would await a command.\r\nSo if I was in the middle of being hysterical and I was shocked, then I would just stop what I was doing and whatever command I was giving next, I would just obey it.\r\n(0:19:13)"}),(0,o.jsx)(t.p,{children:"And that's basically what that program had done.\r\nAt the end of it, we did a bunch of tests and he said congratulations.\r\nHe pulled us in and said, you qualified for Theta. He said he didn't think anybody in the program had it in them to do that, but apparently it was intuitive service or psychic service.\r\nAnd we went on and he brought actual people from... that were versed in meditations and certain techniques that I found since then to be offshoots of the Monroe Institute methods of out-of-body experiences.\r\n(0:19:47)"}),(0,o.jsx)(t.p,{children:"So these are all things you can look up for yourself, but I remember going through that... classes of that.\r\nAnd what they ended up doing was they would give us an IV bag and we would lose consciousness.\r\n(0:20:00)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"And apparently while we were under, we could channel entities or other spirits.\r\nI don't know. I don't know. But it would give them information from past and future events.\r\nSo it was an information gathering device, ultimately what we were turned into from that program.\r\nOne day, out on that same runway, out on that runway, one of these pulled up and all the kids and a few hundred people hopped in.\r\n(0:20:26)"}),(0,o.jsx)(t.p,{children:"This is the closest rendition. I've just grabbed this off the internet of a TR-3B search.\r\nBut I remember that it had these slats in it. And we went out. It was on the runway.\r\nWe walked up the staircase that had been rolled up to it. And it took us to the moon.\r\nAnd I took this slide from drsallowsexopolitics.org. It's a great website, great source of information.\r\n(0:20:49)"}),(0,o.jsx)(t.p,{children:"There have been other witnesses that saw that building as well.\r\nAnd we pulled up to that building. And the pilot, as we were getting close, kind of gave some history about it.\r\nIt was just being finished back then. So that would have been late 82. And he said that they saved a lot of money by using the same designs from the Pentagon. That the Pentagon was built to such strict standards that it was actually easy to convert it to a building that could be in space.\r\n(0:21:16)"}),(0,o.jsx)(t.p,{children:"That could be in as a vacuum. And they made it that shape.\r\nSo I went on there. We got off the ship. And there was an underground hangar behind it.\r\nWe got off the ship and went in. And they performed a couple surgeries on us.\r\nAnd I went right back to Inyokern a day or two later.\r\nSo from there, from Inyokern, we were allowed to rest, finally sleep after weeks of sleep deprivation.\r\n(0:21:49)"}),(0,o.jsx)(t.p,{children:"They loaded us all up on a green bus and took us over to China Lake, which is the next facility over.\r\nWe rode a bus over. This was back in 82. I assume it was an Air Force facility.\r\nThere were a lot of airplanes that were on pedestals.\r\nAnd we went into... everybody was kind of, you know, they weren't in your typical Air Force uniform.\r\n(0:22:10)"}),(0,o.jsx)(t.p,{children:"They were in formal dress, you know, like it was an administrative building.\r\nAnd we went into the elevator and there was an officer with us and other people in the elevator and five of us kids.\r\nAnd he said, don't talk to the doctor. He said, wait a minute.\r\nAnd when those other people got off the elevator, he put a key in and hit a code on the numbers and the elevator kept going down. And when it opened up, it was a train station underground.\r\n(0:22:35)"}),(0,o.jsx)(t.p,{children:"And there were business people and military people that got on there.\r\nI was only on the train about an hour and a half to two hours.\r\nAnd I went from Southern California to Montana. We came up right around Helena, Montana. And the billionaire that owned me at the time, his wife picked me up and drove me back to Seattle, Washington. So this is another area where people always want names and dates.\r\n(0:23:03)"}),(0,o.jsx)(t.p,{children:"And I found it and I've since returned.\r\n(0:23:04)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"So this is one of the better pieces of evidence in my account.\r\nI didn't want to believe it. When I remembered everything in 2015, I didn't want to believe it either.\r\nAnd when I found the house and then I went, oh my God, that's real, it happened.\r\nI wanted help and I reached out to researchers.\r\nAnd Dr. Sala researched me, Rob Potter researched me, and a person named Morgan Starr researched me for about a year and it was like heavy grilling that they put me through.\r\n(0:23:31)"}),(0,o.jsx)(t.p,{children:"At the time here, I went through, it was that island, it was Vashon. I call it Vashon, but the locals call it Vashon, Vashon Island. There was a house there and I was taken there. It was a private home.\r\nAnd the billionaire, he was a practicing Satanist. So unfortunately, another supporting piece of evidence for my account is that in 2015, nobody had connected any kind of Pedogate stuff, any kind of Satanism to any part of government.\r\n(0:24:03)"}),(0,o.jsx)(t.p,{children:"And what he was doing was throwing fundraisers for political local politics.\r\nAnd during the day, thousands of people would come to the property.\r\nAnd at night, he was having parties that were basically like your Pedogate stuff and filming people from a distance so that they could bribe them.\r\nAnd so this is something that I brought out, I testified to in 2015. And to my knowledge, nobody else said anything about it prior to that, at least as far as being connected to the secret space program.\r\n(0:24:34)"}),(0,o.jsx)(t.p,{children:"At that time, that weekend, so I was there, whatever, I was there a few days.\r\nShe kept me in a dog kennel and other kids showed up and then he showed up, the guy that owned me, and they had a ritual human sacrifice.\r\nAnd what they did with myself and two of the other kids, there was another child that they had murdered.\r\nAnd it was like a communion, like you had to eat him.\r\n(0:24:58)"}),(0,o.jsx)(t.p,{children:"And so my guy interviews cut all that stuff out, so sorry if it's dark.\r\nBut after the sacrifice, so that kind of looked like that.\r\nAnd afterwards, that also, I had never had any real experience with Satanism. But some of the researchers that grilled me for that year went and researched and knew about the rituals of Satanism. And it happens basically exactly how I'm describing it here, that they're naked with masks.\r\n(0:25:27)"}),(0,o.jsx)(t.p,{children:"I'm sorry, it's still hard to talk about.\r\nAfterwards, they got dressed and they put us kids on tables and they gave us the IVs. We were carrying our IVs with us.\r\nAnd they put us under.\r\nAnd the other kids went under first and they started saying, you know, crazy stuff, you know.\r\nAnd one girl started just kind of blabbering out.\r\nAnd I lost consciousness and woke up.\r\n(0:25:53)"}),(0,o.jsx)(t.p,{children:"And they were just on top of the world the next day.\r\nAnd apparently we worked.\r\nSo whatever purpose they had trained us for, it worked.\r\n(0:26:03)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"And so the next morning, I was shipped out.\r\nAn airplane came, he had his own runway.\r\nAnd a private propeller airplane came and took me.\r\nAnd I went to Porto, Tawantinsuyo. Do I do this again?\r\nI'm having a hard time with this power switch, man.\r\nPorto, Tawantinsuyo, Peru. So the plane flew to Dallas and I stayed the night on the plane.\r\nAnd then the following morning, we got up and flew to this small town in Peru. Which I was also disappointed to find out exists exactly how I remember it.\r\n(0:26:36)"}),(0,o.jsx)(t.p,{children:"There I was offloaded with a briefcase.\r\nThere was only one guy there that spoke English. He was a younger guy and he was my handler.\r\nAnd I stayed there for two and a half years after that.\r\nAnd what was happening was that they were manufacturing cocaine.\r\nAlong this area is basically where most of the world's coca grows.\r\nAnd they were manufacturing cocaine and then bringing it on the rivers to the town.\r\n(0:27:02)"}),(0,o.jsx)(t.p,{children:"Over here and storing it.\r\nAnd when they had a plane load about once a month, they would fly it to Santa Marta, Colombia. And it's my understanding that prior to me being there, the plane crew went down.\r\nAnd they lost a plane.\r\nSo that they got a hold of whoever owned me or whatever organization and paid for me to be there.\r\nAnd what would happen is they would load up the plane and they'd put me on it and they'd lay me down.\r\n(0:27:27)"}),(0,o.jsx)(t.p,{children:"And I'd put the IV in after we got up in the air.\r\nAnd I was like a canary in the coal mine to them.\r\nSo I would let them know if the weather was bad or if we were off course.\r\nOr whatever was going to happen.\r\nOr if there was police.\r\nAnd then I would wake up in Santa Marta, Colombia. It would wear off after they unloaded and we'd fly back.\r\n(0:27:43)"}),(0,o.jsx)(t.p,{children:"The very first trip, apparently all I said was gibberish.\r\nAnd they were going to kill me.\r\nThey weren't even going to put me back.\r\nThey said they were going to feed me the piranhas.\r\nAnd so they called whoever was in charge of me.\r\nAnd they sent a silver mesh blanket that had EMF blocking.\r\nAnd they said that the electronics from the airplane interfered with whatever state of mind that I was in when they put me under.\r\n(0:28:10)"}),(0,o.jsx)(t.p,{children:"And they wrapped me in an EMF blocking, basically a silver blanket.\r\nAnd the second trip that I went, when they did that, when I woke up from that trip, his attitude was completely different.\r\nAnd after a few more trips, everybody in the entire village was completely different.\r\nHe said that there were times that I spoke fluent Spanish. And I don't know Spanish. He said that I spoke to him as if I was his dead grandmother.\r\n(0:28:32)"}),(0,o.jsx)(t.p,{children:"And after a while, after a few months of that, the people from the town, he would have an entire few pages of questions to ask me while I was under.\r\n(0:28:41)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"So whatever technology that is, that's what was going on.\r\nThere's the town.\r\nThis square, I remember, was being built after our first trip.\r\nThey said that the money from that paid for the excavation to happen, for them to build that plaza in the town.\r\nSo that's... I've researched going there.\r\nI want to go there. I'd love to go back there.\r\nBut everything I've learned about it is that that particular area of Peru is very much like the Wild West. There's a lot of illegal gold mining and there's still a lot of cocaine production.\r\n(0:29:13)"}),(0,o.jsx)(t.p,{children:"And if you go there as a gringo and don't speak Spanish, you stand a good chance of getting hurt.\r\nSo I have not gone back under the advisement.\r\nA friend of mine from Peru, and I begged him to take me.\r\nAnd another friend of mine who I've done interviews with has been to Puerto Maldonado, the next town over.\r\nAnd they all say the same thing. You don't go there.\r\n(0:29:31)"}),(0,o.jsx)(t.p,{children:"You need to learn Spanish and you need to know what you're doing.\r\nSo I have not gone there, but that's a piece of evidence.\r\nThat thing was built right around early 83, right after our first shipment there with the money from the first shipment.\r\nAnd then I stayed. I had a small place.\r\nI think I was like... I would meet them there.\r\nI was over here somewhere, one of these places.\r\n(0:29:52)"}),(0,o.jsx)(t.p,{children:"And I had a little black and white TV and a room with a bathroom.\r\nAnd they would bring me food and basically that was my life.\r\nAnd after going through the trauma mind control program, they called me.\r\nAnd I told them that I'd been to the moon for the surgery.\r\nI said that there's a base on the moon. I told my handler that.\r\n(0:30:09)"}),(0,o.jsx)(t.p,{children:"So they called me Los Loco Peque\xf1o de la Luna. The crazy boy from the moon.\r\nThat was what everybody called me in the town there.\r\nSo after a couple years of that, I think I have the flight path.\r\nThere's the plane. It was a C-46 Commando plane.\r\nAnd I remember crawling up through all the instruments here.\r\nIt was like... got scratchy. It was scratchy.\r\n(0:30:32)"}),(0,o.jsx)(t.p,{children:"There was a lot of stuff here.\r\nAnd being able to look out that window once.\r\nAnd I remember that they always called it the Commando. It was a C-46 Commando. This is an artist rendition of what was taking place.\r\nAgain, they had me wrapped in a blanket.\r\nHe would put an IV in right after we got off the ground.\r\nHe'd put an IV in.\r\n(0:30:52)"}),(0,o.jsx)(t.p,{children:"This is the state of Acre. So right when you leave Peru, north of there is the state of Acre. Right as we were about to leave the state of Acre, he would give me the drug.\r\nAnd I would lose consciousness.\r\nThat was the flight path.\r\nI want to say it was about 10 hours total.\r\n(0:31:11)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"But honestly, I'm not entirely sure.\r\nBut basically, I remember coming down in Santa Marta, Colombia. And that's where they would unload.\r\nAnd they were always uneasy about the people they met there.\r\nRacially, the people in Peru hated the people in Colombia. Or at least in that town.\r\nThat's what my handler said.\r\nThey hated people in Colombia. So after about two years of that, right around puberty, right when I started to hit puberty, I lost the ability.\r\n(0:31:36)"}),(0,o.jsx)(t.p,{children:"Whatever the ability was, I lost it.\r\nAnd when they put me under, I didn't have any kind of insight.\r\nSo they sent me back.\r\nAnd a military plane, like a cargo plane, came and picked me up.\r\nI went back to the island in Seattle. And that's when... so I would have been about 13 till 16 in that 20-year span.\r\nAnd that's when those parties were taking place, the fundraisers.\r\n(0:32:01)"}),(0,o.jsx)(t.p,{children:"I went back there in 2016. And I was in contact with Dr. Sala while I was on my trip.\r\nAnd it was right after the Mount Shasta Conference in 16, when I did my first set of interviews with Dr. Sala for ExoPolitics. And I was in contact with him.\r\nAnd freakishly, I... you know, I can prove it with my family that I'd never been to Seattle or Washington State ever in my life as Tony. But when I was there, and especially when I was on that island, I knew my way around it.\r\n(0:32:30)"}),(0,o.jsx)(t.p,{children:"It was freaky. It was just the strangest, most surreal experience.\r\nThat I knew that beach.\r\nI went there, and I remember her taking us there in my 20 and back.\r\nAnd us kids throwing rocks at each other at the beach.\r\nAnd they were smaller rocks here.\r\nAnd when you got around the corner, they were bigger rocks.\r\nBut I knew that before I'd ever set foot there, you know.\r\n(0:32:49)"}),(0,o.jsx)(t.p,{children:"So that, it was just a freaky thing.\r\nAnd by those memories of my trip there being accurate, I also have to trust that my memories of the space-time were accurate as well.\r\nI thought that when I went to Seattle, when I went to Vashon Island, that I would get surprised and say that... You know, I would see for myself that a lot of what I remembered was vague.\r\n(0:33:10)"}),(0,o.jsx)(t.p,{children:"And entirely the opposite was true.\r\nA lot of what I remembered was accurate.\r\nFreakishly accurate.\r\nSo much that I could tell that things that were built up since then.\r\nLet me see where I'm going.\r\nSo that's a picture I found from a news clipping of one of the parties.\r\nAbout 5,000 people would show up during the day.\r\nAnd, you know, 8 or 9 at night, everybody would leave.\r\n(0:33:30)"}),(0,o.jsx)(t.p,{children:"And later on, close to midnight, it would be a different party.\r\nAnd it was political people, a few hundred people.\r\nAnd it was, you know, they had girls on a stage and us boys.\r\nAnd we were basically sex slaves for them.\r\n(0:33:44)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"Boys would come and go.\r\nThey stayed in the home.\r\nThey kept us away from the girls.\r\nThat went on.\r\nThey had a calendar of events that was nothing like the calendar of events that you and I know.\r\nMost of the time in the summer, it wasn't like an everyday thing, you know, that there was the abuse.\r\nAnd most of the time we were just kids.\r\n(0:34:02)"}),(0,o.jsx)(t.p,{children:"We did calisthenics and we had a swimming pool.\r\nIt was a big house.\r\nIt was about a 6,000 square foot house.\r\nAnd we just lived there like orphans would.\r\nIt was like being an orphan kid.\r\nBut, you know, four or five times during the summer, in the summer months, they had holidays that they would throw these parties.\r\nAnd it was based on, you know, there's no way to sugarcoat it, based on a satanic calendar, a satanic religion.\r\n(0:34:27)"}),(0,o.jsx)(t.p,{children:"So let me go back there.\r\nSo what happened was every day we were taking a couple pills and doing calisthenics.\r\nAnd we were on a tight diet.\r\nWe didn't eat a lot of food.\r\nAnd then the rest of the day we could just lay around and do whatever we wanted.\r\nWe had games.\r\nIt was like being in an orphanage.\r\nOne day they changed the pills and the whatever, something apparently I was allergic to.\r\n(0:34:56)"}),(0,o.jsx)(t.p,{children:"I'm allergic to a few things.\r\nAnd by the third day I was vomiting back up.\r\nI couldn't take the pills.\r\nAnd I asked them, I asked her to call and see if they could change back to the old stuff.\r\nAnd she said, nope, if you can't handle these pills and do what you're supposed to, you're going to be sold to the military.\r\nAnd that's exactly what happened.\r\n(0:35:12)"}),(0,o.jsx)(t.p,{children:"About two weeks later, she drove me to the back, like behind a Walmart. It wasn't a Walmart, but behind a big store in behind it.\r\nAnd two men in a van came, military guys, and they gave me an injection.\r\nAnd I lost consciousness.\r\nAnd when I woke up, I was back on that big ship again, looking my way, on my approach to this building again on the back of the moon.\r\n(0:35:33)"}),(0,o.jsx)(t.p,{children:"Which is basically a joint German Draco base.\r\nYou know, without getting too far ahead of myself, that's what it is.\r\nThere's a military base, the LOC is farther away from this one.\r\nIt's a separate base altogether, but it's infrastructure on the back of the moon.\r\nI went there and was trained more of the same, like the movies, kind of like drugs and movies.\r\n(0:35:58)"}),(0,o.jsx)(t.p,{children:"And military training consisted of only a couple things.\r\nIt was fight or flight response.\r\nEverything that I saw was to train me to not run from a life and death situation.\r\nThey were drilling out, it was a mind control program that got rid of fight or flight response.\r\nBecause ultimately we were not, I wasn't being trained to be a soldier, I was trained to be a support soldier.\r\n(0:36:24)"}),(0,o.jsx)(t.p,{children:"And I don't know how many of you are familiar with the Mars Colony Program, or like I said, not many people know about Randy, Randy Kramer. But he said, he supports my testimony, a lot of the artwork that I sent, that I had done of the bugs, I sent it straight to him.\r\n(0:36:42)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"And he said, yeah, he confirmed it, that's exactly what they looked like, and other people have confirmed it as well.\r\nSo, after that training was done, there was about a dozen of us kids.\r\nThey put us on a transport and took us to a separate base on the moon.\r\nThey marched us, it was U.S. military personnel.\r\nAnd they marched us, we went down elevators and through hallways that were unremarkable.\r\n(0:37:02)"}),(0,o.jsx)(t.p,{children:"There were lines on the walls, but it basically looked like an office building kind of corridor.\r\nAnd when we got to a door at the end, the guy handed us little canisters that were about the size of a Red Bull can, with a red button on top.\r\nHe said, once you walk through that door, those are going to be armed, and as soon as you hit that button, it will detonate and you will die.\r\n(0:37:20)"}),(0,o.jsx)(t.p,{children:"And anything next to you will die, so use it well and try to save someone's life.\r\nThose were our instructions.\r\nWe stood there in line, he said, you know, eyes on shoes, I think is what he said.\r\nWe weren't, you know, looked down.\r\nAnd we waited 15-20 minutes.\r\nThe door opened up and it was a basketball sized arena, like a basketball court size.\r\n(0:37:42)"}),(0,o.jsx)(t.p,{children:"And it had a couple inches of like beach sand on the floor and it was concrete.\r\nAnd you couldn't see because of the way the lights were shining, but there was a crowd, there were spectators.\r\nAnd they were yelling at us.\r\nWe went in one door, the door closed behind us.\r\nThere were about, like I said, about a dozen of us kids, all in teen years, you know, later teens.\r\n(0:38:02)"}),(0,o.jsx)(t.p,{children:"And the door opened on the other side and one of those came out.\r\nAnd that was about 4 feet tall by about 10-12 feet long.\r\nI guess it weighed 300-400 pounds.\r\nIt was terrifying.\r\nIt came out on the other side about a basketball court's distance away and made some sounds.\r\nAnd when it moved toward us, it would move slow, it would move slowly.\r\n(0:38:23)"}),(0,o.jsx)(t.p,{children:"And when it got close, we were all kind of positioned to each other.\r\nWe were pushing each other to get in front of us, you know, we were all in a panic.\r\nAnd one kid from the left just ran right at the thing and detonated that bomb that he was given.\r\nHe was blown in half and the head of that thing was blown pretty much off.\r\n(0:38:42)"}),(0,o.jsx)(t.p,{children:"And it died.\r\nThe crowd cheered.\r\nThe doors that we came in opened up and technicians came in.\r\nI was told later that that kid lived, even though he was literally blown in half.\r\nIt was the closest that he had lived.\r\nWe went in and got medical examinations afterwards.\r\nWe slept in our medical, you know, like in a gurney, like we slept in the medical beds.\r\n(0:39:03)"}),(0,o.jsx)(t.p,{children:"And then the next morning we were taken on another transport to Mars. As soon as I was on Mars, we unloaded and I got on a smaller ship.\r\n(0:39:13)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"And we were taken to a forward base, it was called.\r\nAnd it was largely abandoned.\r\nIt had the ability to have 200 or 300 people in it.\r\nAnd there were maybe 50 or 60 people there.\r\nIt had been abandoned.\r\nAnd it was kind of, it was a remote place.\r\nSo there were five levels of it.\r\nAnd on the lower level was where we were.\r\n(0:39:31)"}),(0,o.jsx)(t.p,{children:"And there was a cafeteria in the middle.\r\nAnd it looked like office space.\r\nAnd they had converted office cubicles for us to sleep in with cots there.\r\nAnd then we had a communal bathroom across the hall.\r\nI was there a couple months, six weeks to a couple months.\r\nWe did three missions where basically we went out this side of this door and hiked during the day.\r\n(0:39:55)"}),(0,o.jsx)(t.p,{children:"We had environmental suits that were white.\r\nAnd we would be escorted with soldiers who had like an armor suit that was camouflaged.\r\nAnd the soldiers had negative buoyancy, which means in the gravity their suits weighed them down enough to where they walked and ran and jumped exactly like they would on Earth. They were weighted so that they felt like the same ratio of weight that they would be on Earth. We were lighter.\r\n(0:40:18)"}),(0,o.jsx)(t.p,{children:"So that if you started to run, it would devolve into kind of a series of hops.\r\nAnd it was hard to do.\r\nWe couldn't move as fast.\r\nIt was less comfortable than the soldiers had.\r\nThe first two outings, I went on three hiking missions basically, three missions.\r\nThe first two were uneventful.\r\nThe third one we had... I don't want to get into... I always waste a lot of time on Mars. And it eats up the later years.\r\n(0:40:49)"}),(0,o.jsx)(t.p,{children:"We were engaged by the bugs.\r\nThere were fatalities.\r\nWe got split up.\r\nThere were six of us that were in white suits like me and two soldiers.\r\nThree of them died.\r\nAt the time, one of those... the bug like I showed you earlier, the big spider one, bit my arm off at the time and held me down.\r\nAnd the other two guys in front of me were killed.\r\n(0:41:11)"}),(0,o.jsx)(t.p,{children:"That's kind of the terrain.\r\nAnd we ended up hot.\r\nLike I said, it devolved into a hop where you would get running and hop, you know, and then fall down and then get up and do it again.\r\nWhen I was there, this came up to me, a mantid.\r\nAnd a lot of people have reported meeting a mantid at some point or another.\r\nI think there are many different kinds of them.\r\n(0:41:38)"}),(0,o.jsx)(t.p,{children:"It came up to me.\r\nAnd the other one was holding me down.\r\nAnd I remember just begging it, don't kill me.\r\nI don't want to die.\r\nI don't want to die.\r\nPlease don't kill me.\r\nAnd I was in a panic.\r\nI was in complete shock.\r\nAnd when it came face to face, it came close to me.\r\nI went into a dream state.\r\n(0:41:57)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"I lost the pain from my arm being severed.\r\nAnd I went into a dream state.\r\nAnd what happened was, I was standing with it in Inyokern, at the air base, where I went through that trauma-based mind control.\r\nAnd it was explaining what it saw to something else.\r\nLike, it was like a dream.\r\nWhere it was standing, you know, like it would be standing here and explaining to somebody else that I didn't know was there, what it saw.\r\n(0:42:22)"}),(0,o.jsx)(t.p,{children:"And we went from the Inyokern. We went to the house in Seattle. We went to the moon base.\r\nAnd then at the very end, it took me to my house that I grew up in, back in Ipsy. Which I had no memory of.\r\nAt the very end, it took me there in my living room.\r\nAnd I was standing there and it said, this is who you are.\r\n(0:42:37)"}),(0,o.jsx)(t.p,{children:"Is what it said.\r\nAnd I had no memory of what, at the time, I didn't know what I was looking at.\r\nIt said, this is who you are.\r\nAnd I woke up and it was like back to the pain and everything.\r\nAnd it walked away.\r\nAnd so it let me live.\r\nThe other, you could tell at the end, there were three or four different kinds of insects.\r\n(0:42:53)"}),(0,o.jsx)(t.p,{children:"And you could tell that they were communicating with each other.\r\nJust by like body language.\r\nBut I couldn't understand.\r\nYou know, it's not like I heard them talking.\r\nAnd the smaller ones had said something to it.\r\nAnd it turned around and said a kind of motion, like okay.\r\nAnd it bit my foot off.\r\nIt bit my foot.\r\nSo we had, the soldiers had auto-tourniquet technology in their suits.\r\n(0:43:11)"}),(0,o.jsx)(t.p,{children:"And we had just one auto-tourniquet on us.\r\nIt was about the size of a pack of cigarettes.\r\nAnd it had a cord on it.\r\nAnd you'd pull the cord out and put it on you and hit a button and it would tourniquet.\r\nSo I used the one on my arm and I crawled up to one of the, they took off.\r\nThey moved in unison and they were gone just as fast as they came.\r\n(0:43:28)"}),(0,o.jsx)(t.p,{children:"I auto-tourniquet, got another one and put it on my foot.\r\nAnd the other two soldiers came and got me.\r\nAnd they were slapping me to keep me awake.\r\nAnd said I couldn't go to sleep.\r\nAnd they hiked me back to that door.\r\nAnd as soon as I saw the door to go back in the base, they let me pass out.\r\nAnd this is kind of a contentious thing where a lot of people, a lot of researchers want more info that I just don't have.\r\n(0:43:50)"}),(0,o.jsx)(t.p,{children:"I passed out when I saw the door.\r\nAnd when I woke up I was in a hospital bed and I had my arm and my foot back.\r\nSo what method they did that, if it was a whole, you know, I don't know.\r\n(0:44:00)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"They grew it.\r\nRandy says that they have holographic beds that can like print your arm out.\r\nI don't know.\r\nI can't confirm or deny it.\r\nBut I woke up and I had my arm and my foot back.\r\nAt that point they determined that the bugs had adapted to the program faster than they expected.\r\nAnd they cancelled it.\r\nExcuse me.\r\nAnd we sat around for a few, a matter of weeks there with nothing to do.\r\n(0:44:24)"}),(0,o.jsx)(t.p,{children:"And a transport came and got us.\r\nAnd I went to a larger underground city on Mars that was basically domes that was under the dirt and taken in.\r\nAnd it looked like, you know, when they processed us, it looked like a resort.\r\nThey were palm trees.\r\nThere was a water feature.\r\nThere was a water fountain.\r\nIt looked like any kind of resort that you would go to in Vegas. But it was under a dome.\r\n(0:44:44)"}),(0,o.jsx)(t.p,{children:"It took us to, I went there and then the officer that had me, escorted us, handed me off.\r\nAnd it was back to schooling where I took aptitude tests to see.\r\nAnd they were tall grays that tested us.\r\nI took aptitude tests to see what kind of job I would be good for.\r\nAnd I went into repair, machine repair or ship repair.\r\nI took, and then that was a series of classes.\r\n(0:45:10)"}),(0,o.jsx)(t.p,{children:"And the guys in the classes were looking at a screen and it would give you a movie and then it would ask you questions.\r\nAnd all you had to do was look at the answer for, you know, for a few seconds and it would blink.\r\nIs this your answer?\r\nAnd you just stayed looking at it and that was the testing.\r\nThere was no writing involved.\r\n(0:45:25)"}),(0,o.jsx)(t.p,{children:"And that went on for weeks that I did that.\r\nThen they loaded us up on a train.\r\nThere were businessmen.\r\nIt was a different train system than anything I'd seen before.\r\nThere were civilians, mostly, like they looked like businessmen that got on it.\r\nAnd the train, and everything was kind of reddish, you know, like that was the theme.\r\nAnd the train lifted, kind of lifted off.\r\n(0:45:49)"}),(0,o.jsx)(t.p,{children:"It was a maglev and took off and there was a, like a bright flash, a poof.\r\nAnd it was disorienting when we woke up, you know, after the poof.\r\nAnd then the train immediately started stopping.\r\nAnd when the door opened and I got off the train, there was a huge hangar and they were German. It was Nazi Germans. There were hundreds of soldiers there that were arriving and there were people like me.\r\n(0:46:13)"}),(0,o.jsx)(t.p,{children:"And there was a guy that handed us, he handed us the pamphlets and he said, when we were called on, we were going to read our oath that we were slaves.\r\nHe said, last month we got slaves and they didn't want, a few of them didn't want to read it.\r\nAnd that's where they, we took them over there and shot them.\r\n(0:46:27)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"And he pointed and there was like a, it looked like a, like a, you know, like a blood stain on the concrete that was dried up.\r\nHe said, is anybody going to get shot today?\r\nAnd we all just sat there and said, he said, good.\r\nAnd I said, line up over there.\r\nAnd when you're called on, read, read the paper.\r\nAnd it was in German. That happened. And then there was an intake.\r\n(0:46:45)"}),(0,o.jsx)(t.p,{children:"I went and got a medical exam, got my hair cut.\r\nAnd I reported, they put us in, the only way for me to describe it is like a prison.\r\nImagine, you know, if you imagine what you've seen a prison look like, but without the bars, without doors.\r\nIt was, it was built just like that, but there were no, there were no doors.\r\nThere were no bars to hold you in.\r\n(0:47:04)"}),(0,o.jsx)(t.p,{children:"You could come and go as you pleased.\r\nBut I reported there and that's where I lived for the next 12 years.\r\nAnd I worked on, let me see, so that, that's, those are the big doors I spoke about earlier.\r\nThat's what they looked like on the inside of the coal trap.\r\nAnd the Germans had found those doors existing.\r\nThey found that system that was already there.\r\n(0:47:24)"}),(0,o.jsx)(t.p,{children:"And the hangar system was so vast that sometimes those doors would get stuck open and not all the air would get let out.\r\nWe could, you could still, you know, for, for hours that those, the air could go out at that rate.\r\nBut it was such a big area that they, and they had air, they had pumps of air that you would, that the pressure would lower.\r\n(0:47:45)"}),(0,o.jsx)(t.p,{children:"There would be low oxygen.\r\nIt would, you'd get headaches and things, but there would still be enough air in there.\r\nLike that's how big of a complex it was.\r\nThat's the other side of Al-Hanamanz and that's the crater I spoke of.\r\nSo from the best of my knowledge, it was in one of these, one of these bigger craters down in a coal trap.\r\n(0:48:02)"}),(0,o.jsx)(t.p,{children:"In that area was where the entrance to, and that was a military entrance.\r\nI learned later on that there were many entrances to several different hangars.\r\nBut this particular one, which was the radio handles pyramid base, was the military one.\r\nThis is not exactly what it looked like, but it's an artist rendition going off what I did, what I described.\r\nThere were a lot of these, whenever they found, they were looking for water.\r\n(0:48:29)"}),(0,o.jsx)(t.p,{children:"There's water on Ceres and they would drain out large caverns.\r\nAnd they said that they were looking for technology.\r\nSo basically ancient ruins inside the water.\r\nBut they would drain out a cavern and begin building human, normal looking buildings inside of it.\r\nBut again, there were these, these were smooth and these were long corridors that would have buildings in them as well.\r\nAnd they were always kind of like a trapezoid shape and smooth.\r\n(0:48:53)"}),(0,o.jsx)(t.p,{children:"Let's see if I have a different slide in here.\r\n(0:48:56)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"So here, here they are again.\r\nThat's kind of what, this is more what they looked like.\r\nSo Ceres was entertaining ETs. So there were different forms of currency there.\r\nPeople there worked and had money.\r\nA lot of the Germans there were really big on the 30 year war in the 1600s. And to them, according to their history on Ceres, that was the first time that humans from Earth had defeated militarily an influence of an extraterrestrial origin.\r\n(0:49:25)"}),(0,o.jsx)(t.p,{children:"That the 30 year war when basically they won, they overthrew the Catholic church and was able to be the Presbyterian religion.\r\nI think the Amish started right then.\r\nThe scenes from the war were, scenes from that were on the back of the money.\r\nThey had German generals, you know, guys with the spiked helmet.\r\nAnd on the back they would have scenes from that, the 30 year war back in the 1600s on the money.\r\n(0:49:49)"}),(0,o.jsx)(t.p,{children:"But the reason I say that they were entertaining extraterrestrials is because they would do that to try to court them to make trade deals with.\r\nAnd one of the caverns, so this is an artist rendition, it's not exact.\r\nBut one of the caverns had a replica of a European city.\r\nI believe it was Copenhagen, I'm not entirely sure.\r\nBut in the entire city inside one of the caverns was a pretty accurate replica of a European city.\r\n(0:50:16)"}),(0,o.jsx)(t.p,{children:"So it was like a tourist attraction.\r\nThe entire place had gravity plating.\r\nSo you're talking about millions and millions of square feet, miles and miles of electrified flooring that created gravity.\r\nAnd the gravity field went about 30 feet up.\r\nSo there were transports that would get lifted out, that would get lifted, people would get on a transport.\r\nAnd it would lift up above 30 feet and then it would be weightless and go to the other end and then dock and be brought down into the gravity.\r\n(0:50:45)"}),(0,o.jsx)(t.p,{children:"And people would get off of it.\r\nA lot of their public transport was like that.\r\nBut again, everything had artificial gravity because it's a small planetoid.\r\nThe hangar bay, this is again an artist rendition.\r\nI'm not much of a sketch artist.\r\nBut there were often ships that were badly damaged being worked on.\r\nThe one on the left here, I remember seeing it and I remember thinking when it had scaffolding that the damage had to be pretty bad.\r\n(0:51:14)"}),(0,o.jsx)(t.p,{children:"All the ships that they had, the trade ships, the cargo ships and the military ones, once they were turned on, they never landed again.\r\nThey were always weightless.\r\nOur ship, my ship that I ended up serving on, I was a cargo engineer, was called the Max von Laue, series colony, diesel shaft Max von Laue. It was hard capped at 10 meters above any surface.\r\n(0:51:38)"}),(0,o.jsx)(t.p,{children:"So they couldn't physically drive it into the ground.\r\nThe computer would stop it from doing that.\r\nAnd so for a ship to be on scaffolding, it was pretty badly damaged and unoperational.\r\n(0:51:48)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"But the hangar bay was made up of miles and miles of like this, a one long corridor with, you know, like bays that ships were pulled into.\r\nAt the end of the hangar, there were times when we, you know, when we got off the ship, we would go and there was a train system there.\r\nOne train would take us right back to where I slept, that prison area.\r\n(0:52:10)"}),(0,o.jsx)(t.p,{children:"And there was another one that connected to the main train system that take you anywhere on the planet.\r\nSometimes some friends of mine that are coworkers, we would walk, you know, and it was a good mile and a half, two miles to this area.\r\nAnd there were revolving doors.\r\nAnd the reason we liked walking that was because once you walked through that door, there was actual, there was proper oxygen on the other side.\r\n(0:52:32)"}),(0,o.jsx)(t.p,{children:"So you would get, you know, you'd feel kind of exhausted.\r\nOnce you got through that door, that first few breaths was kind of like a rush because it was oxygenated.\r\nThe hangar, as I said, always had the doors opening and closing, had a low oxygen environment.\r\nRight before I left, the year that I left, they were in the middle of carving those horses out of the columns that were natural columns formed.\r\n(0:52:53)"}),(0,o.jsx)(t.p,{children:"And they had brought in artists and they were working on it for quite some time.\r\nAgain, the theme for the Germans on Ceres was horses and the 30-year war in the 1600s. The train system kind of looked like that.\r\nMark is a great artist, Mark Halsey is a great guy.\r\nHe drew this corner, it wasn't like that.\r\nBut trains would pull up and there was a glass door that would open.\r\n(0:53:18)"}),(0,o.jsx)(t.p,{children:"And when it did, you had to stand behind this line because it would suck air in.\r\nThey were in a vacuum tube.\r\nAnd if you were anywhere in this line, you could get sucked in and get hurt.\r\nThere was a big whoosh when the door opened.\r\nAnd then the train doors would open.\r\nAnd every train stop had a map of the planet.\r\nAnd it would show you the train routes and the different cities that were there.\r\n(0:53:39)"}),(0,o.jsx)(t.p,{children:"And it was quite often they added new ones.\r\nIt was under constant construction and constant expansion.\r\nReal estate was a big deal to them.\r\nThey were always expanding.\r\nThat's just another artist area.\r\nThere was a long corridor that went to one of those bigger ones that was like a city area.\r\nI used to walk that quite a bit.\r\nAnd there was running water.\r\n(0:53:58)"}),(0,o.jsx)(t.p,{children:"In here, there was like a river that this bridge went over.\r\nThere weren't cars.\r\nThe police and the EMF people, the emergency services, had little six-wheeled carts.\r\nElectrical carts that they drove around.\r\nBut nobody had their own car that was there.\r\nSo it's hard to explain.\r\nBut basically, as a slave, I wore a collar.\r\nAnd I wore a jumpsuit that identified me as such.\r\n(0:54:28)"}),(0,o.jsx)(t.p,{children:"It opened up a lot of ridicule when I went into public places.\r\n(0:54:32)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"Quite often, if I was on a train and there was a seat and I was sitting down and there was somebody that came on that didn't have a seat available, they would make me get up and get to the back of the train.\r\nWhen I went into public areas, when I went into the city areas, I was basically constantly under the threat of being abused because I was a slave.\r\n(0:54:51)"}),(0,o.jsx)(t.p,{children:"It was very humiliating.\r\nSo as a result, I stayed in places that were kind of out of the ordinary.\r\nAnd one of the first places I went to was a joke from one of the officers on the ship that told me when I went into town for the first time to go to the Red Light District. And I didn't have any idea what he meant by that, and I did.\r\n(0:55:11)"}),(0,o.jsx)(t.p,{children:"And it's a long story, but I was basically given free access to a club there, a bar that was basically like a brothel, like a strip club in the Red Light District. And I could go there and just sit there and drink waters and I didn't have to pay.\r\nAnd so I would go there in my spare time.\r\nAnd, you know, the girls that were working there were slaves as well, and I was just one of them.\r\n(0:55:34)"}),(0,o.jsx)(t.p,{children:"So I would go there, but this is the foyer to that.\r\nAnd the reason why it's significant is because that piece of art, this thing, had zero gravity in it.\r\nIt was an area where they just turned off the gravity of the floor.\r\nAnd it would shoot fire, balls of fire would go in it, and, you know, they would make a ball of, like a butane gas, I don't know, but it was a fire.\r\n(0:55:56)"}),(0,o.jsx)(t.p,{children:"And it would pop, like, and then shoot across the thing, and then it would shoot balls of water, and they would kind of mingle.\r\nAnd then every few minutes the gravity would come on, the water would splash, and it would start again.\r\nIt would shoot. And I remember just being memorized by that, mesmerized by that thing.\r\nI would sit and look at it as long as I could, but in the foyer, whenever somebody else came in, they said, you know, you're a slave, you can't be here.\r\n(0:56:16)"}),(0,o.jsx)(t.p,{children:"Get in there, either leave or get in there, whatever you're going to do, you can't just stay here.\r\nSo this was an existing structure.\r\nOne of the caverns that the Germans had emptied water out of had rooms in it.\r\nAnd these doors that opened up were existing. These catwalks were not.\r\nThe Germans built that, and they built this, they built the elevator system, and it went quite deep.\r\n(0:56:42)"}),(0,o.jsx)(t.p,{children:"There was a friend of mine that I would go visit, and it took about 40 minutes for me to get there.\r\nAnd it was about a 15-minute train ride, and about 25 minutes of riding lifts down is how deep it went.\r\n(0:56:56)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"It went basically for miles down vertical.\r\nThe doors looked like that. Those, like I said, those were existing. The Germans had found those, and they converted the inside of those to apartments.\r\nAnd the doors worked telepathically, so you could walk up to the door and think, I'm here.\r\nAnd it would let the person on the inside know, and they could grant you access, and they could even tell you to go away.\r\n(0:57:19)"}),(0,o.jsx)(t.p,{children:"And I was told that they could even cause you pain, that they'd go away, and if you didn't leave, it could actually cause you to have headaches or bad headaches until you left.\r\nAnd then it would slide to the side and open up.\r\nSo at the end of my time, I was taken on a disc back to the moon and put through a regression process that a lot of other people in the 20 and back described as well.\r\n(0:57:49)"}),(0,o.jsx)(t.p,{children:"Basically, they made me stay still for, it felt like weeks, and they gave injections every day of some, you know, some drug or whatever, but I wasn't allowed to move.\r\nThey said if you moved, you could injure yourself.\r\nAnd then at the end of it all, when it was done, they kind of put me in a machine, and it was painful.\r\nAnd I woke up back in a base, I believe on the moon base here, with my old memories, now with no memory of the 20 and back, but my old memories again.\r\n(0:58:16)"}),(0,o.jsx)(t.p,{children:"So I've speculated, it's my theory that they're doing it with cloning, that they can clone a person, and the clone is kind of a vegetable, some that can't really get up and walk around, and they take, you know, Randy Kramer calls it quantum super fluid consciousness, that they can take your consciousness out, or at least partially, so that you still go live your life, and put it in the clone, and then it goes and lives, and then they can just kill the clone, or whatever they do to it, and the consciousness returns naturally.\r\n(0:58:47)"}),(0,o.jsx)(t.p,{children:"And so that, you know, the time travel component, who knows what's going on with that.\r\nI'm only speculating. Like I said to some people earlier, you know, you can go for kidney surgery, that doesn't mean you know how to do kidney surgery when you wake up.\r\nMy 20 and back was kind of the same way. There's a lot of things, there's a lot of questions that I have unanswered, that I can only speculate.\r\n(0:59:07)"}),(0,o.jsx)(t.p,{children:"But I think that they are using a cloning technology. I think I was a clone during that time.\r\nAnd after, let me see if this is the next slide. So, after the 20 years, not only myself, but others, and I don't want to name them for whatever copyright infringement, but other people that have experienced 20 and backs that have come forward, all have regained their memory of the process well after the 20 years.\r\n(0:59:32)"}),(0,o.jsx)(t.p,{children:"So, over here. So, like I said, I had bits and pieces through here, but that didn't make any sense.\r\n(0:59:40)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"But I didn't get the real memory recall until really 2015 when it all kind of came in big chunks and it solidified into a full, you know, the full memories that I could remember from A to B. And that's how it happens. So, I think that there's definitely a consciousness thing that goes on.\r\nRight around the year 2000, about 18 years after it, I woke up one day and I kind of got my act together.\r\n(1:00:07)"}),(0,o.jsx)(t.p,{children:"So, after that person, whatever, died or was put back, I had a deep personality change in my real life at that time.\r\nAnd it really wasn't until then that I got organized and became an adult. I was kind of a basket case before that.\r\nSo, I think that's part of it. I think that they're borrowing part of your consciousness and driving clones with it.\r\n(1:00:29)"}),(0,o.jsx)(t.p,{children:"And I think that at some point that when you remember things, it's not stored in the body, that there's somewhere else that all our memories are stored that I have access to.\r\nAgain, I had an MRI in late April of 15 and about two weeks after that is when I had the big memory recall.\r\nThere's a thing called the Mars records, if I say his name right, it's Ralph, Michael Ralph, that had the same thing.\r\n(1:00:53)"}),(0,o.jsx)(t.p,{children:"He had an MRI and then he recalled service on Mars as well.\r\nSo, it's a coincidence, it's worth mentioning, and that's how it happened to me as well.\r\nSince then, since I've done interviews, I've been contacted by about 2,000 people that all have similar experiences or similar memories.\r\nMemories of serving in a secret space program and being put back.\r\nAll of them, most of them don't have all the details or it's hard for them to put together a string of 10 years of memories or at least they don't want to talk about it.\r\n(1:01:28)"}),(0,o.jsx)(t.p,{children:"But like I said, about 2,000 people have reached out to me so far and I still get about two a week that have memories of going through some kind of service.\r\nAnd it's kind of like the same, everybody has the same kind of side effects from it.\r\nAnd I found that when you get into a diagram like this, when I ask them, when did it start?\r\n(1:01:49)"}),(0,o.jsx)(t.p,{children:"And then I roll the clock forward 20 years and say, okay, so if that was in 1990, what happened in 2010? Do you have anything?\r\nAnd most of them go, wow, now that you mention it, I did have a life change.\r\nUsually about 20 years later, in their real life down here, they have some other personality change that happens.\r\nBecause essentially that other self that's coexisting on the timeline dies.\r\n(1:02:15)"}),(0,o.jsx)(t.p,{children:"And so that's what I found in my own research. That was me. This picture was taken the weekend after.\r\nSo that was April of 82. My dad snuck out and took pictures of me playing out in the yard.\r\n(1:02:26)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"So I found this and I thought, you know, I can remember that because that next day when I went to school, I was a completely different person.\r\nI was a completely different kid. I was nothing, I had no memory of the 20 and back, but I was not a kid anymore.\r\nAnd I didn't have, when I, I remember playing in the driveway that, that weekend.\r\n(1:02:46)"}),(0,o.jsx)(t.p,{children:"And now that I look at this picture and I was wondering what the hell happened to me.\r\nThe next day I went to school when I went to use the bathroom and it's not a big school.\r\nI went there my whole life, but I didn't remember where it was because of the sensation of being gone for 20 years was real.\r\nLike I woke up and had breakfast with my parents the next morning and I was back in my life and I thought, I haven't seen you guys in 20 years.\r\n(1:03:08)"}),(0,o.jsx)(t.p,{children:"And my older sister said, don't be stupid, you know, you were just, we just had dinner last night.\r\nBut I remember sitting there with that sensation of being returned into my life that was after all that time.\r\nI think that's it. So there's a website. I'll make that available with all my interviews.\r\nIf this one goes on YouTube, I'll put that there. Links to all my interviews.\r\n(1:03:28)"}),(0,o.jsx)(t.p,{children:"I've done 60 or 70 by now and counting and I try to keep them all on a website.\r\nI don't do this for money and I don't have a website. I'm not promoting anything.\r\nI am working on a book because there's demand. I get asked for it a lot.\r\nThat was me.\r\n(1:03:46)"}),(0,o.jsx)(t.p,{children:"I went to Gaia Studios. I was on season 13 of Cosmic Disclosure. They cut out all the satanic stuff because they've had their own, I guess their own issues with it.\r\nBut it's heavily edited. Gaia was good to me. It was a good experience.\r\nJay Weidner also said that, I think Jason Rice, if none of you are familiar with him, he was on the season prior to me.\r\n(1:04:05)"}),(0,o.jsx)(t.p,{children:"I had never met him or heard any of his info, but a lot of the things that he said, I told Jay as well and Jay told me that.\r\nThere's Randy Kramer and George Norrie. I went and taped last year for George Norrie's Beyond Belief. I don't think it's aired yet. I don't even know if it will air.\r\nThe interview was kind of really fast paced and it's hard to explain anything.\r\n(1:04:26)"}),(0,o.jsx)(t.p,{children:"So anybody that doesn't know my story I think would be lost in that interview, but it may have aired, I don't know.\r\nThat's the car she was in.\r\nSo I want to... my original slideshow of this... I still have a few minutes.\r\nMy original slideshow presentation, I did this in Australia and I had given names.\r\nBecause since then I found the CIA program that I went through in Inyokern. I found the funding from the CIA, the declassified online CIA library.\r\n(1:04:55)"}),(0,o.jsx)(t.p,{children:"And I found some stuff with the techniques we were taught.\r\n(1:04:59)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"And so I went and edited out the names because it's just safer for my health to do that.\r\nBut the people in charge of the program from the institute I found and they checked out to be exactly how I remember.\r\nI put that there. That was at Inyokern. So this is a document. It's pretty blurry.\r\nBut it's basically the funding prior to the gateway program for the CIA which was remote viewing.\r\n(1:05:30)"}),(0,o.jsx)(t.p,{children:"It was an offshoot. The program I was in was called Project Grill Flame. So these are documents from 1982 dictating the funding and who would be in charge of it.\r\nThat's the info. That's the website where I found a lot of info about Grill Flame. I don't know if you guys are just into it as a hobby or want to do any kind of research.\r\n(1:05:52)"}),(0,o.jsx)(t.p,{children:"I would tell everybody, research everything.\r\nAnything that I told you, if you're curious about it, research it.\r\nYou can look me up on Facebook. I love answering questions.\r\nHopefully we can do some questions today.\r\n20 years is a lot of time and to talk about it in an hour, hour and a half, I leave a lot out.\r\nJust for time.\r\nThis was a document about Grill Flame. This was a thing about Dr. Jolly West who was involved in Grill Flame from the Stanford Research Institute. And all it does is it connects him to the MKUltra stuff.\r\n(1:06:25)"}),(0,o.jsx)(t.p,{children:"And he pioneered, not only brought the MKUltra to the remote viewing research, but he also pioneered sleep deprivation.\r\nSo lo and behold, after I had talked about all that in 2015, I found this info about a year ago.\r\nTying them in. So there's more about West's work.\r\nAnd he said he figured out ways to do the trauma-based mind control based on sleep deprivation.\r\n(1:06:47)"}),(0,o.jsx)(t.p,{children:"And had, well, they don't say what happened, but they say he had tremendous results.\r\nAnd they also said there's a film where they said they had tremendous results with near-death experience with children.\r\nWhere they had tremendous results, but they didn't go into anything after that.\r\nThere's some documents about the, there's a CIA declassified document about Project Gateway. I'll also try to make that available online to anybody who wants to see it.\r\n(1:07:10)"}),(0,o.jsx)(t.p,{children:"That's a really good read. What it does is explains how consciousness works based on Isaac Benthove's Swinging the Wild Pendulum book.\r\nWhich is basically married quantum mechanics with quantum consciousness theory.\r\nAnd explains how ESP works.\r\nThere's the Monroe Institute focus chart on focus levels.\r\nWhere you can go into meditative states through hemi-sync techniques.\r\nAnd do out-of-body and excess past and future events.\r\nThis is from the book, Isaac Benthove's Stalking the Wild Pendulum, I think is the name of the book.\r\n(1:07:48)"}),(0,o.jsx)(t.p,{children:"And what this is, says is that your consciousness, your brain right now has brain waves.\r\nAnd in a certain, when you're in focus one, which means hopefully you're all still awake.\r\n(1:07:58)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"And if you're not sleeping, then you're in focus one.\r\nAnd when you go to sleep, you get to a focus three or four.\r\nAnd when you get to a focus ten, you know, your brain waves start to take a different shape.\r\nAnd what happens is, the smallest distance in our universe, because it's based on quantum holograph theory, the smallest distance is a Planck distance.\r\n(1:08:20)"}),(0,o.jsx)(t.p,{children:"Kind of like resolution on a TV screen, only millions of times smaller, a Planck distance.\r\nAnd what happens when a brain wave, or your consciousness wave, begins to get to a certain frequency, when it changes direction, right here, it occupies less distance than a Planck. So it clicks out of time-space and gives you access to past and future events.\r\nAnd basically, that's the science behind ESP. People that can do remote viewing, people that can do, you know, all of it.\r\n(1:08:48)"}),(0,o.jsx)(t.p,{children:"There's a lot of research on it, you know, you don't have to look far if you put in ESP research.\r\nBut basically that's, in a nutshell, that's how it works.\r\nThe science behind it is that your brain waves, at a certain state of mind, let me get back, at a certain state of mind, your brain waves happen so quickly, that they change direction in less than a Planck distance and click out into beyond time-space. So that gives you access to the future or the past.\r\n(1:09:15)"}),(0,o.jsx)(t.p,{children:"So this is from the CIA document.\r\nAgain, it's really a good read for anybody that's interested.\r\nIt explains a lot of the science behind it.\r\nIt also, this one, this particular one just explains on some of the results they got when the Army did the, they used Army personnel for the experiments.\r\nThey got a lot of results about it.\r\nThey found that they could go into an astral state and they could go into remote view and find people.\r\n(1:09:42)"}),(0,o.jsx)(t.p,{children:"And if they did what was called color breathing, like basically in a dream state.\r\nIf I went and found you, Miles, in the dream and imagined bathing you in the color blue, then you had a tangible, they would have somebody far away, sometimes on the other side of the country.\r\nAnd they'd have two or three guys go into that state of mind with drugs and with the hemisink tones.\r\n(1:10:05)"}),(0,o.jsx)(t.p,{children:"And they would go there and just imagine going over somebody and bathing them in the color blue.\r\nAnd what they found was that it lowered their heart rate, they felt less pain and it would heal them.\r\nIt would lower swelling. They would do it to people that were injured in combat and it would relieve swelling.\r\nThey also found that if they did it with the color red, they would cause heart problems.\r\n(1:10:25)"}),(0,o.jsx)(t.p,{children:"And they could cause, they could induce swelling.\r\nAnd one of the researchers from the SRM, I'm not going to say his name, said that they were actually able to murder people doing that.\r\n(1:10:34)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"There were other color breathings, I forget the other.\r\nBut anyhow, this is a great read for anybody that's interested.\r\nAnd again, this is not just some random bullshit.\r\nThis was off the CIA website of their declassified library.\r\nAnd these were things they did coincidentally back in 82. And there's the cover of the book. And I'm done.\r\nThank you very much.\r\nSo thanks.\r\nThank you.\r\n(1:11:09)"}),(0,o.jsx)(t.p,{children:"So if we have a few minutes, I'm okay with answering questions, if anybody.\r\nI was fortunate enough to speak to the Houston chapter of MUFON last night with a Zoom meeting.\r\nAnd I gave them the same slideshow and basically said the same stuff.\r\nAnd I entertained questions.\r\nYou know, the skeptical questions I like as well.\r\nI wanted my wife to prove me wrong in the beginning and ask me all the questions she could.\r\n(1:11:37)"}),(0,o.jsx)(t.p,{children:"And so I entertained the questions.\r\nIf anybody's curious about anything, feel free to ask.\r\nAnyone have any questions?\r\nOkay. I want to make sure everyone knows that you're welcome to go to the other room and enjoy the music and refreshments.\r\nOr if you'd like to stay here and remain for a Q&A session with Mr. Rogers. Does anyone have a question?\r\nWhat triggered the return of the memories of the 20 years?\r\n(1:12:05)"}),(0,o.jsx)(t.p,{children:"And what was that experience like? How did it all come back?\r\nSure. Well, again, you know, there were some coincidental things that happened in succession in a matter of a two-week period from the last week of April in 2015. Like, I always had vague memories, but they didn't make sense.\r\nI got an MRI, which, like I said, is in line with the Mars Records account with that Michael Relf got an MRI and then recalled his service.\r\n(1:12:30)"}),(0,o.jsx)(t.p,{children:"But about two weeks later, I also saw the ExoPolitics interviews with Randy Kramer, where he explained the time travel component.\r\nBecause the things that I did remember, I did remember flying over Ceres and looking out the window of the ship. I did remember that.\r\nBut I always told myself, when could that have happened?\r\nI always had chronological memories of my life, you know, like I can remember growing up and never being in space.\r\n(1:12:56)"}),(0,o.jsx)(t.p,{children:"And those memories in space, I have memories of being a professional, of having a job, of getting up and getting there.\r\nSo I told myself, when could that have possibly happened?\r\nI told myself, it must be a dream or something.\r\nOnce I saw Randy Kramer's explanation of 20 and back, where they put you back in time.\r\n(1:13:14)"}),(0,o.jsx)(t.p,{children:"Not only do they take you for 20 years, but they put you back. And I went, holy shit, that happened.\r\nOnce I entertained and I accepted those memories, then I could go back and remember the things that I had denied, that I had kind of, you know, forced out, you know, that I didn't entertain.\r\nOnce I entertained, then big chunks, then it all came back.\r\n(1:13:33)"}),(0,o.jsx)(t.p,{children:"It came in big chunks and it was very disorienting.\r\n(1:13:35)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"I was kind of a basket case for three months.\r\nI didn't want to keep it to myself and I wanted someone to talk to.\r\nAnd I reached out to researchers, not so that I could go out and do interviews.\r\nI just wanted counseling. I knew that if I was going to go to a regular... I even looked in the book for counseling.\r\nAnd I knew that as soon as I went to a regular professional counselor, I was going to get in big trouble, you know, to say any of this stuff.\r\n(1:13:58)"}),(0,o.jsx)(t.p,{children:"So I reached out to researchers in the field in hopes of talking to others in the way of counseling. And I ended up being asked to do interviews.\r\nAnd I've been doing interviews ever since.\r\nAnd talking about it has proven to be the best therapy.\r\nSo anybody that goes through it as well, that's my advice.\r\nFind somebody you trust.\r\n(1:14:18)"}),(0,o.jsx)(t.p,{children:"If it's not a friend in your life, which it's usually hard to, find somebody online, do a, whatever, Facebook, phone call, whatever, and talk about it. That's been the best therapy.\r\nThank you. Another question?\r\nI thought that we spoke a moment ago, and it's a lot of this type of stuff.\r\nAnd my question is, in the programs that you were in, has anybody ever told you, or is there any discussion about, who's actually in charge of, or as far as who's really running the show, if the service population is not allowed to go into space, or is there a special club, or who's in charge here?\r\n(1:14:54)"}),(0,o.jsx)(t.p,{children:"So, I get asked that quite a bit.\r\nThe answer that I have for you is definitely, I don't know for sure.\r\nThe Germans that I worked for, worked for what is called the Draco, who had, their main base was around Jupiter. So there are several space stations around Jupiter, that is close to a natural portal system, that can access other galaxies.\r\nSo ships can go extra galactic there.\r\n(1:15:18)"}),(0,o.jsx)(t.p,{children:"There was a base there by the Draco, that the Germans answered to, and they had a treaty with, and that's kind of like who they worked for.\r\nAnd according to them, that's who had control of not only the Earth, but the whole solar system. That was their territory, and everybody had to ask permission.\r\nBut that's not how space works.\r\nA lot of people are, a lot of the lies, we've been told, we've been told that it takes a long time to get from A to B. You know, all our space shows, show us it takes a long time to fly into another planet, and that's not the case.\r\n(1:15:48)"}),(0,o.jsx)(t.p,{children:"It's an instantaneous thing, and we came back every day at the end of the day.\r\nThat was one thing, and then the other thing is that there's only a handful of E.T. races out there that are players in the political landscape, and that's not true either. There are billions of civilizations, and all on their own different level of technology.\r\n(1:16:08)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"The ones that are higher, that have higher technology, just ignore the ones that have lower technology.\r\nThe same way we do when we walk through the woods, and we come across animals.\r\nWe just ignore them, and they go their way.\r\nWe don't interact, and that's what's going on.\r\nThey come into our solar system, and if they need something, they need genetics, they need to come to Earth for an experiment, or whatever it is, they do so, and they don't need to ask permission if they're on a certain level of tech.\r\n(1:16:31)"}),(0,o.jsx)(t.p,{children:"So, but below a certain level of tech, below the Draco level of tech, they are beholden to the Draco, who have a military presence.\r\nSo, if that answers your question.\r\nHello, Tony. Hello. Man, it's mind-blowing. It's a big pill to swallow, and I hate to talk to it.\r\nI don't like to force this info on anybody that doesn't answer.\r\nNo, it's great, man. It's always, it's something I feel.\r\n(1:17:04)"}),(0,o.jsx)(t.p,{children:"I have one quick question, but I don't want to go up to time, because I can't. So, in terms of UMass, is there any kind of protection?\r\nIs there any kind of law?\r\nIs there any type of, are we just subject to whatever higher technology extraterrestrials?\r\nAre we just subject to them?\r\nIf they choose to do this, or choose to do that, are we just like helpless like ants?\r\n(1:17:30)"}),(0,o.jsx)(t.p,{children:"That's a great question, and that's the first time I've been asked that in front of a crowd.\r\nI have been asked that before.\r\nYou know, without getting into like, you know, real spiritually going into that, because I think that everybody's intake of spiritual information is their own.\r\nYou know, I don't want to affect your relationship with what you believe.\r\nBut the answer to your question is, the protection against that is us.\r\n(1:17:57)"}),(0,o.jsx)(t.p,{children:"You know, on a subconscious level, you're a higher mind than what we are when we interact with each other.\r\nAnd you have to give permission, and we do.\r\nThe earth as a whole is an entity, is an organism.\r\nAnd we are parts of it. We are part of it.\r\nSo there is a level of protection.\r\nThere is a level of permission that has to happen for anything to happen.\r\n(1:18:18)"}),(0,o.jsx)(t.p,{children:"You know, like I said, this takes my talk into a completely different direction to really go there with it.\r\nBut, you know, I have my own personal beliefs. I'm heavy into the law of one.\r\nI believe in God. You know, I believe in a lot of things.\r\nThat just, you know, that I feel right with.\r\nYou know, and that's what everybody should believe in.\r\n(1:18:38)"}),(0,o.jsx)(t.p,{children:"What they feel is right. What you feel is good.\r\nNot because somebody tells you it.\r\nBut I think of us as, you know, we're being held back.\r\nSomeone asked, yesterday I got asked, how come in the last 50 years we've advanced so far?\r\nAre they helping us? Do the ETs help us?\r\n(1:18:57)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"The truth is, for the last 2,000 years, they've held us back.\r\nThey've been holding us back.\r\nWe should have been advanced long ago.\r\nBecause that's what we naturally are.\r\nWe're an advanced species. We're an advanced intelligence.\r\nAnd so we're catching up to where we should have been in the first place.\r\nAnd that's going to be our protection.\r\nYou know, when... I say this too, if anybody's following... Is anybody here aware of the Artemis program?\r\n(1:19:21)"}),(0,o.jsx)(t.p,{children:"Artemis. Please look that up.\r\nNASA just announced in 2024 we're going back to the Moon. Like Apollo was a Greek god, his sister was Artemis. And that's the Artemis program.\r\nIn four years we're going to have people on the Moon. So I think the original plan for disclosure... And this is me completely speculating.\r\nThis is not an official announcement or anything, okay?\r\nBut I think the original plan to disclose ET, extraterrestrials, was to go to the Moon and find artifacts.\r\n(1:19:53)"}),(0,o.jsx)(t.p,{children:"And at that point we would go, look, there's artifacts here.\r\nSomebody built a building here.\r\nAnd then we would be contacted by a Nordic race or a human-looking race that would come down and say, now you've found evidence.\r\nNow we can contact you. And that would spur it, you know, disclosure.\r\nAnd then they shot Kennedy and they swept the whole thing on the rug.\r\n(1:20:12)"}),(0,o.jsx)(t.p,{children:"We went, we did Apollo, nothing was found.\r\nBoom, we haven't gone back.\r\nNow I think the landscape has changed.\r\nPeople like me that came forward in the past got killed quick.\r\nAnd so there are a lot of people talking nowadays about it.\r\nAnd I think that all of a sudden Artemis is just going to go back to the Moon in a fucking election year on top of it.\r\n(1:20:30)"}),(0,o.jsx)(t.p,{children:"And Cramer, Randy Cramer said that that's one of the plans to disclose is that at the end of a presidency, that in the middle of a presidency, the president would look weak if he didn't know anything about it.\r\nYou were supposed to be briefed, you're president, you should know.\r\nBut at the end of a presidency, the president could claim, I didn't know anything about it.\r\n(1:20:49)"}),(0,o.jsx)(t.p,{children:"And the next president could come and go, I didn't know anything about it either.\r\nWow, we got ETs. So it's a coincidence to me.\r\nIt's kind of a telling sign that Artemis is in 2024 when we're going to be at the end of our next election.\r\nSo that I think they're going to go to the Moon. They're going to go to the South Pole. And I think they're going to disclose from the Moon. And that's going to kick it off.\r\n(1:21:07)"}),(0,o.jsx)(t.p,{children:"And I think once that happens, a lot of people are going to... I think people are ready for it. I mean, face it.\r\nPeople are ready for it.\r\nIt's not going to be a biggest shock to the belief system as it would have been even 20, 30 years ago.\r\n(1:21:18)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"I think we're ready now.\r\nSo I think that's what's going to happen in 5, 10 years.\r\nWe're going to have the official account of it.\r\nEven though we've been... there's an infrastructure and we've been up there for a long time.\r\nThere's 100 years we've been up there already.\r\nI think we're going to get an official announcement in the next 5 to 10 years.\r\n(1:21:34)"}),(0,o.jsx)(t.p,{children:"And I think that'll be our best defense, like you said.\r\nWe're not just ants. We're an intelligent species.\r\nAnd subconsciously we can direct the course of our own destiny.\r\nWe choose our own destiny.\r\nAny other questions?\r\nI don't know if you've seen the movie Inception where they dream within a dream within a dream and they kind of go extract information.\r\nYep. Have you ever heard of anything like that used for, you know, going into people's lives?\r\n(1:22:09)"}),(0,o.jsx)(t.p,{children:"Well, yeah.\r\nYes. So... So not only trauma-informed, not only trauma-based mind control, but there's... with the grain-based mind control where it's, you know, builds you up, there are levels of mind control all around us.\r\nWe are all under some sort of influence of mind control from the commercials, from the TV. There's talk of there's a wave in the... Everything you watch on TV that there's a wave, there's a wave that you can't hear that affects you and irritates you.\r\n(1:22:41)"}),(0,o.jsx)(t.p,{children:"And they unirritate you when the commercials come on and when you're watching the show the wave comes on and kind of has a light irritation.\r\nAnd when they hit you with a product, the irritation goes away so that you go, oh, man, I want some Coca-Cola. You know, I mean, without... I'm not pointing a finger, but there are versions of mind control around all of us that is very advanced and it's very far away from what we even think is possible.\r\n(1:23:02)"}),(0,o.jsx)(t.p,{children:"As far as the Inception thing, about going into dreams, that goes back to the Gateway Project. If you want to go and read up on the... just go to the CIADclassified.gov, I think it is.\r\nGo to that website and just put in Gateway or do dream research, any of those things and it will uncover documents that go into that.\r\nBut Gateway was a lot about that.\r\n(1:23:24)"}),(0,o.jsx)(t.p,{children:"They were going into... they were getting soldiers and psychics into dream states and then having them remote view.\r\nAnd there's actually been quite a bit of documentation about it.\r\nIt's a real thing.\r\nI'd like to add, you were a pioneer, and I believe you can.\r\nThere's a lot of things to say about that.\r\nI'm sure you've heard a lot about it.\r\nThanks for sharing this with us.\r\n(1:23:53)"}),(0,o.jsx)(t.p,{children:"Just a quick question.\r\nYou said there's about 2,000 people that have contacted you so far, since you came out about this.\r\nThat's a lot of people, number one.\r\nAnd are they all reporting the same thing, where they basically lived their whole life, but there's just one of the errors, a missing time, that they felt they were away and have all these memories, but they don't kick back in.\r\n(1:24:14)"}),(0,o.jsx)(t.p,{children:"And also the MRI experience.\r\n(1:24:17)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"Have you ever had any condition on your eyes or exposure to strong magnetic fields where you think it might cause you to jog more memories?\r\nI looked into that.\r\nI actually wanted to build one for all these people that were coming forward.\r\nIt's not like you can just walk into the hospital and make yourself have an MRI. It's a prescription-based procedure.\r\nAs far as the 2,000 people, they all have different... many of them have completely different experiences.\r\n(1:24:46)"}),(0,o.jsx)(t.p,{children:"I think that that's a testament to how many different programs or how many different species, and at different levels of technology, are interacting with people on the earth.\r\nSome people have very... some people, their testimony is positive.\r\nThey get taken, and they have good things happen to them.\r\nSome people have had worse things than me happen where you wouldn't believe some of the awful things, and a lot of people don't want to talk about it.\r\n(1:25:12)"}),(0,o.jsx)(t.p,{children:"They're just... they're just shocked by the things they remember.\r\nSo it's all across the board.\r\nSome people just have bits and pieces, fragments.\r\nI call them keystone memories, and some people remember quite detailed things.\r\nAnd I always tell them the same thing.\r\nWrite a timeline up, write it down, and write a timeline, and go from there because your memories will keep coming if you want to remember.\r\n(1:25:33)"}),(0,o.jsx)(t.p,{children:"Now, the other thing is, when I was going back, I wanted to remember.\r\nI did not want to forget my life there.\r\nAnd a lot of people on that, I remember talking to over on the other side, wanted to forget because they had witnessed bad things, you know, very bad things.\r\nSo I think that affects your ability to recall as well.\r\nBut yeah, I generally get about two people a week that have some kind of weirdness, you know, whether it's a memory like that, but that contact me and say, you know, help, can you... is there any way you can help me remember?\r\n(1:26:04)"}),(0,o.jsx)(t.p,{children:"And it's usually the same stuff.\r\nI go back and forth with them about, you know, meditate, get your mind at a good place, get your diet right, and write down a timeline and just focus on the keystone memories, the things that you remember clearly, the clearest, and then more memories will come.\r\nAnd that seems to work for most people.\r\nThere are other things.\r\n(1:26:23)"}),(0,o.jsx)(t.p,{children:"There's the hypnosis.\r\nThere are other, some treatments.\r\nThere's a Reiki version of it.\r\nA lot of people volunteer to do it on me, but they want me to come out west, go out west, and it's like, you know, I have a normal life.\r\nSo, there are many different methods, but there's a lot of people.\r\nIt's not just me, and it's not just one or two people.\r\n(1:26:45)"}),(0,o.jsx)(t.p,{children:"Like I said, just, there's 2,000 that I know of, and there's got to be plenty more than that.\r\nI'm not the most, you know, I don't get the biggest hits on YouTube. So, when you talk about, when you get out to millions of people, there's a percentage, you know, probably three or four percent of everybody that sees my videos reach out.\r\n(1:27:04)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"So, that means there's quite a bit of people that have had this happen.\r\nAny other questions?\r\nI have one particular question.\r\nI believe it was Randy Kramer that claimed to have been genetically produced because he had certain types of psychic abilities.\r\nCan you speak to these controllers, or whatever, these programs, how they genetically select individuals to expand their career?\r\nRight, well, absolutely.\r\nLike I said, they tested me for my genetics in the very beginning.\r\n(1:27:43)"}),(0,o.jsx)(t.p,{children:"And we had to wait there for quite some time to see if I had the genetics compatible to the tech that they were going to use.\r\nSo, it's like not everybody can go, at least for whatever program that they want.\r\nSo, certain types of enhancement require certain types of genetics.\r\nAnd so, you know, as far as the life-extending technology, the 20 and back, or that, I don't know if everybody is capable of going for that.\r\n(1:28:08)"}),(0,o.jsx)(t.p,{children:"So, in Randy Kramer's case, and a lot of other people, they are manipulating their genetics almost from birth.\r\nEven some people prenatal, they're manipulating their genetics.\r\nYou know, the MyLab programs are doing it prenatal.\r\nAnd then as the kids grow up, they're testing them and manipulating their genetics so that they can enter into the programs.\r\nOkay, great.\r\nIf there's any other questions, let's give Andy Rodriguez, Anthony Rodriguez a round of applause.\r\n(1:28:37)"}),(0,o.jsx)(t.p,{children:"Thanks, it's a pleasure to be here.\r\nThank you.\r\n(1:28:40)"})]}),"\n",(0,o.jsx)(t.p,{children:"(2024-12-21)"})]})}function w(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>h});var a=n(296540);const o={},r=a.createContext(o);function i(e){const t=a.useContext(r);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(r.Provider,{value:t},e.children)}},905537:e=>{e.exports=JSON.parse('{"permalink":"/ds/en/blog/2024/12/21/_tony_rodrigues_lec","source":"@site/blog/2024-12-21_tony_rodrigues_lec.md","title":"Tony Rodrigues \u306e\u8b1b\u6f14\u52d5\u753b : \u6587\u5b57\u8d77\u3053\u3057","description":"\u524d\u7f6e\u304d","date":"2024-12-21T00:00:00.000Z","tags":[{"inline":false,"label":"UFO","permalink":"/ds/en/blog/tags/UFO","description":"UFO \u95a2\u9023"},{"inline":false,"label":"need_ai","permalink":"/ds/en/blog/tags/need_ai","description":"AI \u306b\u3088\u308b\u8981\u7d04/\u5206\u6790\u3092\u4e88\u5b9a"},{"inline":false,"label":"amendmark","permalink":"/ds/en/blog/tags/amendmark","description":"amendmark"},{"inline":false,"label":"2024-12","permalink":"/ds/en/blog/tags/2024-12","description":"2024-12"}],"readingTime":87.91,"hasTruncateMarker":true,"authors":[],"frontMatter":{"tags":["UFO","need_ai","amendmark","2024-12"]},"unlisted":false,"prevItem":{"title":"Alejandro Rojas + John Greenewald \u5bfe\u8ac7 : \\"Davis/Wilson \u30e1\u30e2\\"\u3001MJ-12 \u8cc7\u6599 \u3092\u5de1\u308b UFO \u696d\u754c\u306e\u59ff\u52e2\u3092\u6279\u5224","permalink":"/ds/en/blog/2024/12/21/rojas_greenwald"},"nextItem":{"title":"William Pawelec \u306e\u8a3c\u8a00 \u21d2 \u634f\u9020","permalink":"/ds/en/blog/2024/12/20/pawelec"}}')}}]);